parameters.jsonBody:
={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What are the latest demographic and behavioral trends among {{ $json.target_segment }} in {{ $json.geography }}? Include data on technology adoption rates, spending behavior, work patterns, and how this segment is changing in 2025-2026. Use recent reports from McKinsey, Bain, NASSCOM, or similar."}],
  "search_recency_filter": "month"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What is the current market size, growth rate, and TAM/SAM for {{ $json.product_category }} targeting {{ $json.target_segment }} in {{ $json.geography }}? Include latest statistics, CAGR projections, and any recent market sizing reports from 2025-2026."}],
  "search_recency_filter": "month"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "How are buying behaviors and decision-making processes changing for {{ $json.target_segment }} when purchasing {{ $json.product_category }}? What channels, content formats, and messaging approaches are working best in 2025-2026?"}],
  "search_recency_filter": "month"
}

parameters.text:
=Synthesize demographic research into actionable go-to-market intelligence.

Target Segment: {{ $('Set Analysis Config').item.json.target_segment }}
Product: {{ $('Set Analysis Config').item.json.product_category }}
Geography: {{ $('Set Analysis Config').item.json.geography }}

Demographic Trends:
{{ $('Fetch Demographic Trends').item.json.choices[0].message.content }}

Market Size Data:
{{ $('Fetch Market Size Data').item.json.choices[0].message.content }}

Behavioral Shifts:
{{ $('Fetch Behavioral Shifts').item.json.choices[0].message.content }}

Return JSON:
{
  "market_size_tam": "",
  "market_growth_rate": "",
  "ideal_customer_profile_update": "",
  "segment_trends": [],
  "buying_behavior_shifts": [],
  "best_acquisition_channels": [],
  "messaging_that_resonates": [],
  "segment_risks": [],
  "product_implications": [],
  "monthly_summary": "3-4 sentence strategic summary"
}

=👥 *Monthly Demographic Report — {{ $now.toFormat('MMMM yyyy') }}*

{{ $json.monthly_summary }}

*Market:* {{ $json.market_size_tam }} | Growth: {{ $json.market_growth_rate }}

*Segment Trends:*
{{ $json.segment_trends.slice(0,3).map(t=>`• ${t}`).join('\n') }}

*Best Acquisition Channels:*
{{ $json.best_acquisition_channels.slice(0,3).map(c=>`• ${c}`).join('\n') }}

*Messaging That Resonates:*
{{ $json.messaging_that_resonates.slice(0,2).map(m=>`• ${m}`).join('\n') }}
